package com.meterflow.credits;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.util.*;
@Service public class CreditService{private final CreditAccountRepository accounts;private final CreditNoteRepository notes;public CreditService(CreditAccountRepository a,CreditNoteRepository n){accounts=a;notes=n;}
@Transactional public CreditAccount topUp(String customer,String currency,BigDecimal amount){var a=accounts.lockByCustomer(customer).orElseGet(()->accounts.save(new CreditAccount(customer,currency)));if(!a.getCurrency().equals(currency))throw new IllegalArgumentException("Credit currency must match account currency");a.add(amount);return accounts.save(a);}
@Transactional public CreditNote issueNote(String customer,String currency,BigDecimal amount,String reason){if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Credit note amount must be positive");var note=notes.save(new CreditNote(customer,amount,currency,reason));var a=accounts.lockByCustomer(customer).orElseGet(()->accounts.save(new CreditAccount(customer,currency)));if(!a.getCurrency().equals(currency))throw new IllegalArgumentException("Credit note currency mismatch");a.add(amount);return note;}
@Transactional public BigDecimal apply(String customer,String currency,BigDecimal amount){var a=accounts.lockByCustomer(customer).orElseGet(()->accounts.save(new CreditAccount(customer,currency)));if(!a.getCurrency().equals(currency))throw new IllegalArgumentException("Credit currency mismatch");return accounts.save(a).consume(amount);}
public CreditAccount balance(String c){return accounts.findByCustomerId(c).orElseGet(()->new CreditAccount(c,"BDT"));}public List<CreditNote> notes(String c){return notes.findByCustomerIdOrderByCreatedAtDesc(c);}}
